def describe_eternal_intelligence_architecture() -> str:
    lines = [
        "TitanAI Eternal Intelligence Architecture Era",
        "",
        "This era focuses on TitanAI becoming a permanent digital engineering partner that continuously understands, protects, maintains, improves, documents, and evolves software over the long term.",
        "",
    ]
    for capability in ETERNAL_INTELLIGENCE_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
